script.lang:
insert into amp_global_settings(id,settingsName,settingsValue,possibleValues,description, section)
values (nextval('amp_global_settings_seq'), 'Recreate the views on the next server restart','true','t_Boolean','Recreate the views on the next server restart', 'general');

CREATE OR REPLACE VIEW v_amp_organisations AS
SELECT amp_org_id AS id, name AS value FROM amp_organisation;

INSERT INTO amp_global_settings(id, settingsName, settingsValue, possiblevalues, description, section)
VALUES (nextval('amp_global_settings_seq'), 'Internal Ecowas Donor',
(SELECT id FROM v_amp_organisations WHERE value = 'ECOWAS'),
'v_amp_organisations', 'Internal Ecowas Donor', 'funding');
